/bin/bash -lc 'set -e
probe_dir=$(find "$PWD/tmp" -maxdepth 1 -type d -name '"'amarnath-verify.*' | sort | tail -1)
python3 - \""'$probe_dir" <<'"'PY'
from html.parser import HTMLParser
from pathlib import Path
import sys, re, urllib.parse, base64
class P(HTMLParser):
    def __init__(self): super().__init__(); self.in_h2=False; self.a=None; self.buf=[]; self.rows=[]
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if tag=='h2': self.in_h2=True
        if self.in_h2 and tag=='a': self.a=d.get('href'); self.buf=[]
    def handle_data(self, data):
        if self.in_h2: self.buf.append(data)
    def handle_endtag(self, tag):
        if tag=='h2' and self.in_h2:
            title=' '.join(''.join(self.buf).split())
            self.rows.append((title,self.a)); self.in_h2=False; self.a=None; self.buf=[]
for f in sorted(Path(sys.argv[1]).glob('search_*.html')):
    print('\\nFILE', f.name)
    p=P(); p.feed(f.read_text(errors='ignore'))
    for title,url in p.rows[:12]:
        print(title, '\\t', urllib.parse.unquote(url or ''))
PY"

