from html.parser import HTMLParser
import sys,re
class P(HTMLParser):
 def __init__(self): super().__init__(); self.inrow=False;self.cells=[];self.cur=[];self.rows=[]
 def handle_starttag(self,t,a):
  if t=='tr': self.inrow=True;self.cells=[];self.cur=[]
  elif self.inrow and t in ('td','th'): self.cur=[]
 def handle_data(self,d):
  if self.inrow:self.cur.append(d)
 def handle_endtag(self,t):
  if self.inrow and t in ('td','th'):
   self.cells.append(' '.join(''.join(self.cur).split()));self.cur=[]
  elif t=='tr' and self.inrow:
   self.rows.append(self.cells);self.inrow=False
for row in P().rows: pass
p=P();p.feed(open(sys.argv[1],errors='ignore').read())
for row in p.rows:
 s=' | '.join(row)
 if re.search('mathura',s,re.I): print(s)
