import sys
class P(HTMLParser):
 def __init__(self): super().__init__(); self.h=False;self.a=None;self.b=[];self.rows=[]
 def handle_starttag(self,t,a):
  d=dict(a)
  if t in ('h2','h3','h4') and d.get('class','').find('entry-title')>=0:self.h=True
  if self.h and t=='a':self.a=d.get('href');self.b=[]
 def handle_data(self,d):
  if self.h:self.b.append(d)
 def handle_endtag(self,t):
